ALIASES = {"Московская область": "Москва и Московская область", "Ленинградская область": "Санкт-Петербург и Ленинградская область"}

def canonical_region(region: str | None):
    if not region:
        return None
    return ALIASES.get(region, region)

def _name_pattern(name: str):
    escaped = re.escape(name).replace(r"\ ", r"\s+")
    return re.compile(rf"(?<![А-Яа-яЁё0-9-]){escaped}(?![А-Яа-яЁё0-9-])", re.I)

def find_place(text: str, region: str | None):
    region = canonical_region(region)
    if not region or region not in PLACES or not text:
        return None
    for name, coords in sorted(PLACES[region].items(), key=lambda item: len(item[0]), reverse=True):
        if _name_pattern(name).search(text):
            return {"place": name, "lat": coords[0], "lon": coords[1], "approximate": True}
    return None
